  "inlineSchema": "// NutriApp — Prisma Schema\n// Convention: snake_case for all DB fields; camelCase in application code via Prisma mapping.\n\ngenerator client {\n  provider      = \"prisma-client-js\"\n  // Include musl (Alpine) targets for Docker; \"native\" covers macOS dev\n  binaryTargets = [\"native\", \"linux-musl-arm64-openssl-3.0.x\", \"linux-musl-openssl-3.0.x\"]\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// ─── Enums ────────────────────────────────────────────────────────────────────\n\nenum Gender {\n  MALE\n  FEMALE\n  OTHER\n}\n\nenum ActivityLevel {\n  SEDENTARY\n  LIGHT\n  MODERATE\n  ACTIVE\n  VERY_ACTIVE\n}\n\nenum Goal {\n  LOSE_WEIGHT\n  MAINTAIN\n  GAIN_MUSCLE\n}\n\nenum FoodSource {\n  USDA\n  OPEN_FOOD_FACTS\n  CUSTOM\n}\n\nenum MealTime {\n  BREAKFAST\n  LUNCH\n  DINNER\n  SNACK\n}\n\n// ─── Models ───────────────────────────────────────────────────────────────────\n\nmodel User {\n  id             String        @id @default(cuid())\n  email          String        @unique\n  password_hash  String\n  name           String\n  age            Int\n  weight_kg      Float\n  height_cm      Float\n  gender         Gender\n  activity_level ActivityLevel\n  goal           Goal\n  created_at     DateTime      @default(now())\n  updated_at     DateTime      @updatedAt\n\n  meals      Meal[]\n  daily_logs DailyLog[]\n\n  @@map(\"users\")\n}\n\nmodel Food {\n  id                      String     @id @default(cuid())\n  name                    String\n  brand                   String?\n  // All nutritional values stored per 100g — multiply by (quantity_g / 100) for actual values\n  calories_per_100g       Float\n  proteins_per_100g       Float\n  carbs_per_100g          Float\n  fats_per_100g           Float\n  fiber_per_100g          Float\n  // Extended metrics — populated for processed foods; null for whole foods\n  sugar_per_100g          Float?\n  saturated_fats_per_100g Float?\n  salt_per_100g           Float?\n  source                  FoodSource\n  external_id             String? // e.g. Open Food Facts barcode\n  created_at              DateTime   @default(now())\n\n  meal_foods MealFood[]\n\n  @@map(\"foods\")\n}\n\nmodel Meal {\n  id          String   @id @default(cuid())\n  // null user_id = global template (read-only for users)\n  user_id     String?\n  name        String\n  is_template Boolean  @default(false)\n  created_at  DateTime @default(now())\n  updated_at  DateTime @updatedAt\n\n  user            User?          @relation(fields: [user_id], references: [id], onDelete: Cascade)\n  meal_foods      MealFood[]\n  daily_log_meals DailyLogMeal[]\n\n  @@map(\"meals\")\n}\n\n/// Junction table linking foods to meals with portion size.\nmodel MealFood {\n  id         String @id @default(cuid())\n  meal_id    String\n  food_id    String\n  quantity_g Float // Portion size in grams\n\n  meal Meal @relation(fields: [meal_id], references: [id], onDelete: Cascade)\n  food Food @relation(fields: [food_id], references: [id])\n\n  @@map(\"meal_foods\")\n}\n\n/// Stores daily nutritional targets as a snapshot at creation time.\n/// IMPORTANT: target_* fields must NEVER be recalculated from User retroactively.\n/// If the user changes their goals, new DailyLogs get new targets; old ones remain intact.\nmodel DailyLog {\n  id              String   @id @default(cuid())\n  user_id         String\n  date            DateTime @db.Date\n  // Snapshot of targets at log creation — decoupled from current User goals\n  target_calories Float\n  target_proteins Float\n  target_carbs    Float\n  target_fats     Float\n  created_at      DateTime @default(now())\n  updated_at      DateTime @updatedAt\n\n  user            User           @relation(fields: [user_id], references: [id], onDelete: Cascade)\n  daily_log_meals DailyLogMeal[]\n\n  // One log per user per day\n  @@unique([user_id, date])\n  @@map(\"daily_logs\")\n}\n\n/// Records a meal being consumed at a specific time within a daily log.\nmodel DailyLogMeal {\n  id           String   @id @default(cuid())\n  daily_log_id String\n  meal_id      String\n  meal_time    MealTime\n  logged_at    DateTime @default(now())\n\n  daily_log DailyLog @relation(fields: [daily_log_id], references: [id], onDelete: Cascade)\n  meal      Meal     @relation(fields: [meal_id], references: [id])\n\n  @@map(\"daily_log_meals\")\n}\n",
